CREATE TABLE communication_preferences(tenant_id uuid NOT NULL,customer_id uuid NOT NULL,email_enabled boolean NOT NULL DEFAULT true,sms_enabled boolean NOT NULL DEFAULT false,whatsapp_enabled boolean NOT NULL DEFAULT false,operational_enabled boolean NOT NULL DEFAULT true,promotional_enabled boolean NOT NULL DEFAULT false,preferred_language varchar(8) NOT NULL DEFAULT 'en' CHECK(preferred_language IN ('en','ta')),consent_note varchar(500) NOT NULL,consent_recorded_at timestamptz NOT NULL DEFAULT now(),consent_recorded_by uuid NOT NULL,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,customer_id),FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id));
CREATE TABLE communication_preference_audit(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,customer_id uuid NOT NULL,actor_id uuid NOT NULL,preferences jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
